-- REPETITION (lecture seule) -- genere par phase2/checks/ventes_reglees_famille1_generer_patch_2026-11-27.py (son mot du 27/11)
select (select string_agg(app_affaire_id || '=' || coalesce(vente_reglee_app, '-') || ' / ' || coalesce(numero_facture_app, '-'), ' ; ' order by app_affaire_id) from public.app_affaire_ledger where app_affaire_id in (3650, 14115, 20674, 30835, 30828, 30844, 30834, 30846, 30847)) as les_9_ventes,
  (select count(*) from public.app_classeur_realignement_journal where lot = 'ventes_reglees_famille1_2026-11-27') as journal_attendu_18,
  (select count(distinct l.app_chaine_id) from public.app_affaire_ledger l where l.kind = 'vente' and coalesce(l.vente_reglee_app, '') <> '' and l.app_chaine_id is not null and not exists (select 1 from public.app_affaire_repartition r where r.app_chaine_id = l.app_chaine_id)) as ventes_reglees_sans_part_attendu_0,
  (select count(distinct l.app_chaine_id) from public.app_affaire_ledger l where l.kind = 'vente' and coalesce(l.vente_reglee_app, '') <> '' and exists (select 1 from public.app_affaire_repartition r where r.app_chaine_id = l.app_chaine_id) and not exists (select 1 from public.app_affaire_repartition r where r.app_chaine_id = l.app_chaine_id and coalesce(r.origine, '') not like 'hektor%')) as reglees_sur_supposition_seule_attendu_20,
  (select md5(coalesce(string_agg(concat_ws('|', app_affaire_id, kind, state, app_chaine_id, app_dossier_numero, coalesce(vente_reglee_app, '-'), coalesce(numero_facture_app, '-'), coalesce(date_annulation_app, '-'), coalesce(motif_annulation_app, '-'), coalesce(honoraires_entree_app::text, '-')), ';' order by app_affaire_id), '')) from public.app_affaire_ledger where app_affaire_id in (3650, 14115, 20674, 30835, 30828, 30844, 30834, 30846, 30847)) as empreinte_apres;
